import sys
import math
from collections import defaultdict

MOD = 10**9 + 7

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def dfs(v, p, tree, beauties, gcd_values):
    for u in tree[v]:
        if u == p:
            continue
        gcd_values[u] = gcd(beauties[u], gcd_values[v])
        dfs(u, v, tree, beauties, gcd_values)

def main():
    input = sys.stdin.readline
    n = int(input())
    beauties = list(map(int, input().split()))
    tree = defaultdict(list)

    for _ in range(n - 1):
        a, b = map(int, input().split())
        tree[a].append(b)
        tree[b].append(a)

    total_sum = 0

    for root in range(1, n + 1):
        gcd_values = [0] * (n + 1)
        gcd_values[root] = beauties[root - 1]
        dfs(root, -1, tree, beauties, gcd_values)

        for v in range(1, n + 1):
            total_sum = (total_sum + gcd_values[v]) % MOD

    print(total_sum)

if __name__ == "__main__":
    main()
